package com.lqq.supportflow.eventing.application;
import com.lqq.supportflow.eventing.*; import com.lqq.supportflow.eventing.domain.*; import org.springframework.context.ApplicationEventPublisher; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class DispatchOutboxService { private final OutboxPort outbox; private final ApplicationEventPublisher publisher; public DispatchOutboxService(OutboxPort outbox,ApplicationEventPublisher publisher){this.outbox=outbox;this.publisher=publisher;} @Transactional public int dispatch(int limit){int published=0;for(OutboxEvent event:outbox.pending(limit)){publisher.publishEvent(new PublishedOutboxEvent(event.id(),event.tenantId(),event.eventType(),event.payload()));outbox.markPublished(event.id());published++;}return published;}}
